const parseChecklistData = (csvData: string): Record<string, GeneratedTask[]> => {
  const checklists: Record<string, GeneratedTask[]> = {};
  const tempMap: Record<string, { seq: number; task: GeneratedTask }[]> = {};

  const lines = csvData.trim().split('\n');
  const startIndex = lines[0].startsWith('Sequence') ? 1 : 0;

  for (let i = startIndex; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;

    const firstComma = line.indexOf(',');
    const lastComma = line.lastIndexOf(',');

    if (firstComma === -1 || lastComma === -1 || firstComma === lastComma) {
      continue;
    }

    const seqStr = line.substring(0, firstComma);
    let title = line.substring(firstComma + 1, lastComma);
    const code = line.substring(lastComma + 1).trim();

    if (title.startsWith('"') && title.endsWith('"')) {
      title = title.substring(1, title.length - 1);
    }
    title = title.replace(/""/g, '"');

    if (!tempMap[code]) {
      tempMap[code] = [];
    }

    tempMap[code].push({
      seq: parseFloat(seqStr) || 0,
      task: {
        task: title,
        description: title
      }
    });
  }

  Object.keys(tempMap).forEach(code => {
    checklists[code] = tempMap[code]
      .sort((a, b) => a.seq - b.seq)
      .map(item => item.task);
  });

  return checklists;
};

export const STATIC_CHECKLISTS: Record<string, GeneratedTask[]> = parseChecklistData(RAW_CHECKLIST_DATA);
